1	// Command ledger 是本地器具校准台账的命令行入口。
2	//
3	// 用法：
4	//
5	//	ledger -f 台账文件.json <子命令> [参数]
6	//
7	// 数据只保存在 -f 指定的本机文件中；不指定时使用当前目录下的 ledger.json。
8	// 不同文件是互不混入的不同台账，退出后再次打开同一文件可继续查询和操作。
9	package main
10	
11	import (
12		"encoding/json"
13		"errors"
14		"flag"
15		"fmt"
16		"io"
17		"math"
18		"os"
19		"strconv"
20		"strings"
21	
22		"github.com/bengzyyys/calibration-ledger/calibrate"
23	)
24	
25	const usageText = `本地器具校准台账（仅本机，不连接真实实验室）
26	
27	用法：
28	  ledger -f <台账文件> [--json] <子命令> [参数]
29	
30	子命令：
31	  register   登记器具：--id 编号 --name 名称 --allowed 允许绝对误差
32	  status     切换状态：--id 编号 --status 在用|停用|待校准
33	  cert       录入证书：--instrument 器具编号 --number 证书编号 \
34	             --cal-date YYYY-MM-DD --expiry YYYY-MM-DD \
35	             --method 方法 --error 测得误差 --summary 摘要
36	  use        申请使用器具：--id 编号（允许与拒绝都会留痕）
37	  review     按器具核对：--id 编号
38	  list       列出全部登记器具
39	  plan       建立校准计划：--instrument 器具编号 --number 计划编号 \
40	             --date YYYY-MM-DD --note 非空说明
41	  reschedule 计划改期：--number 计划编号 --date 新日期 --reason 非空原因
42	  cancel     取消计划：--number 计划编号 --reason 非空原因
43	  complete   用证书完成计划：--number 计划编号 --certificate 证书编号
44	  todos      校准待办：[--instrument 器具编号]（默认全部未结束计划）
45	
46	通用参数：
47	  -f, --file   台账文件路径（默认 ledger.json）
48	      --json   以 JSON 输出结果
49	
50	退出码：0 成功；1 业务拒绝或未找到；2 参数或读写错误。
51	`
52	
53	// options 是所有子命令共用的全局参数。
54	type options struct {
55		file   string
56		asJSON bool
57	}
58	
59	func main() {
60		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
61	}
62	
63	func run(args []string, stdout, stderr io.Writer) int {
64		if len(args) == 0 {
65			fmt.Fprint(stderr, usageText)
66			return 2
67		}
68		var opts options
69		fileSet := false
70		cmd := ""
71		businessArgs := make([]string, 0, len(args))
72		// 全局参数（-f/--file、--json）既可以写在子命令前，也可以与器具编号、
73		// 证书编号等业务参数交错写在子命令之后。这里先从左到右扫描整条命令行，
74		// 剥除全局参数并确定最终台账路径，再打开该文件：因此 -f 出现的位置不会
75		// 改变它选中的台账；同一次调用出现多个文件参数时，短名与长名共同参与
76		// 从左到右的顺序，以最后一次明确给出的路径为准。
77		// 子命令的业务标志（--method、--summary 等）都需要值：不带等号时紧跟的
78		// 下一个参数就是它的值。值必须原样保留为字段内容——即使它看起来是
79		// -f、--file=…、-f… 或 --json，也不参与台账选择与输出格式设置；
80		// 只有出现在完整字段之外（或子命令之前）的同名写法才是全局参数。
81		for i := 0; i < len(args); i++ {
82			a := args[i]
83			if cmd == "" && !strings.HasPrefix(a, "-") {
84				// 第一个不以“-”开头的参数是子命令；其后的位置参数仍要继续扫描。
85				cmd = a
86				continue
87			}
88			switch {
89			case a == "-f" || a == "--file" || a == "-file":
90				if i+1 >= len(args) {
91					fmt.Fprintf(stderr, "%s 需要一个值\n", a)
92					return 2
93				}
94				i++
95				opts.file = args[i]
96				fileSet = true
97			case strings.HasPrefix(a, "--file="):
98				opts.file = a[len("--file="):]
99				fileSet = true
100			case strings.HasPrefix(a, "-file="):
101				opts.file = a[len("-file="):]
102				fileSet = true
103			case strings.HasPrefix(a, "-f="):
104				opts.file = strings.TrimPrefix(a, "-f=")
105				fileSet = true
106			case strings.HasPrefix(a, "-f") && len(a) > 2:
107				opts.file = a[2:]
108				fileSet = true
109			case a == "--json" || a == "-json":
110				opts.asJSON = true
111			case a == "--" && cmd != "":
112				// “--” 终止后续标志解析：其后的参数原样交给子命令
113				// （与此前 flag 包的行为一致），即使其中出现 -f 也不再视为全局参数。
114				businessArgs = append(businessArgs, args[i:]...)
115				i = len(args)
116			default:
117				if cmd == "" {
118					fmt.Fprintf(stderr, "未知全局参数 %s\n\n%s", a, usageText)
119					return 2
120				}
121				businessArgs = append(businessArgs, a)
122				// 业务标志不带等号时，下一个参数是它的字段值：原样一并转交子命令，
123				// 绝不再按全局参数解释（与 flag 包对字符串标志的取值行为一致）。
124				// 值缺失时不在这里补，由子命令解析时报“标志需要值”。
125				if strings.HasPrefix(a, "-") && !strings.Contains(a, "=") && i+1 < len(args) {
126					i++
127					businessArgs = append(businessArgs, args[i])
128				}
129			}
130		}
131		if fileSet {
132			if strings.TrimSpace(opts.file) == "" {
133				fmt.Fprintln(stderr, "台账文件路径不能为空或只有空白")
134				return 2
135			}
136		} else {
137			opts.file = "ledger.json"
138		}
139		if cmd == "" {
140			fmt.Fprint(stderr, usageText)
141			return 2
142		}
143		cmdArgs := businessArgs
144		if cmd == "help" || cmd == "-h" || cmd == "--help" {
145			fmt.Fprint(stdout, usageText)
146			return 0
147		}
148	
149		// 最终路径确定之后才打开台账：被后续 -f 覆盖掉的旧路径与默认文件
150		// 即使损坏或不可读，也不会影响对有效目标文件的操作。
151		l, err := calibrate.Open(opts.file)
152		if err != nil {
153			fmt.Fprintln(stderr, "打开台账失败：", err)
154			return 2
155		}
156	
157		switch cmd {
158		case "register":
159			return cmdRegister(l, cmdArgs, opts, stdout, stderr)
160		case "status":
161			return cmdStatus(l, cmdArgs, opts, stdout, stderr)
162		case "cert":
163			return cmdCert(l, cmdArgs, opts, stdout, stderr)
164		case "use":
165			return cmdUse(l, cmdArgs, opts, stdout, stderr)
166		case "review":
167			return cmdReview(l, cmdArgs, opts, stdout, stderr)
168		case "list":
169			return cmdList(l, cmdArgs, opts, stdout, stderr)
170		case "plan":
171			return cmdPlan(l, cmdArgs, opts, stdout, stderr)
172		case "reschedule":
173			return cmdReschedule(l, cmdArgs, opts, stdout, stderr)
174		case "cancel":
175			return cmdCancel(l, cmdArgs, opts, stdout, stderr)
176		case "complete":
177			return cmdComplete(l, cmdArgs, opts, stdout, stderr)
178		case "todos":
179			return cmdTodos(l, cmdArgs, opts, stdout, stderr)
180		default:
181			fmt.Fprintf(stderr, "未知子命令 %q\n\n%s", cmd, usageText)
182			return 2
183		}
184	}
185	
186	// newFlagSet 构造子命令自己的标志集。台账文件与 --json 已在打开台账前
187	// 从整条命令行统一解析，这里只保留 --json 的登记，绝不在此处重新登记
188	// -f/--file：否则子命令后的文件参数会指向与已打开台账不同的路径。
189	func newFlagSet(name string, opts *options) *flag.FlagSet {
190		fs := flag.NewFlagSet(name, flag.ContinueOnError)
191		fs.SetOutput(io.Discard)
192		fs.BoolVar(&opts.asJSON, "json", opts.asJSON, "以 JSON 输出")
193		return fs
194	}
195	
196	func parseFloat(stderr io.Writer, raw, field string) (float64, bool) {
197		v, err := strconv.ParseFloat(strings.TrimSpace(raw), 64)
198		if err != nil || math.IsNaN(v) || math.IsInf(v, 0) {
199			fmt.Fprintf(stderr, "%s 必须是有限数字\n", field)
200			return 0, false
201		}
202		return v, true
203	}
204	
205	func emit(opts options, stdout, stderr io.Writer, human string, v any) int {
206		if opts.asJSON {
207			raw, err := json.MarshalIndent(v, "", "  ")
208			if err != nil {
209				fmt.Fprintln(stderr, "输出 JSON 失败：", err)
210				return 2
211			}
212			fmt.Fprintln(stdout, string(raw))
213			return 0
214		}
215		fmt.Fprint(stdout, human)
216		return 0
217	}
218	
219	// failBusiness 处理业务拒绝：退出码 1，原记录未被改动。
220	func failBusiness(opts options, stdout, stderr io.Writer, err error, rejected any) int {
221		if opts.asJSON {
222			raw, _ := json.MarshalIndent(rejected, "", "  ")
223			fmt.Fprintln(stdout, string(raw))
224		}
225		fmt.Fprintln(stderr, "已拒绝：", err)
226		return 1
227	}
228	
229	func failIO(stderr io.Writer, err error) int {
230		fmt.Fprintln(stderr, "操作失败：", err)
231		return 2
232	}
233	
234	func cmdRegister(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
235		fs := newFlagSet("register", &opts)
236		id := fs.String("id", "", "器具唯一编号")
237		name := fs.String("name", "", "器具名称")
238		allowed := fs.String("allowed", "", "允许的绝对误差（不小于零的有限数）")
239		if err := fs.Parse(args); err != nil {
240			fmt.Fprintln(stderr, "register 参数错误：", err)
241			return 2
242		}
243		if *id == "" || *name == "" || *allowed == "" {
244			fmt.Fprintln(stderr, "register 必须提供 --id、--name、--allowed")
245			return 2
246		}
247		allowedErr, ok := parseFloat(stderr, *allowed, "允许的绝对误差")
248		if !ok {
249			return 2
250		}
251		inst, err := l.Register(calibrate.RegisterInput{
252			ID: *id, Name: *name, AllowedError: allowedErr,
253		})
254		if err != nil {
255			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
256				return failBusiness(opts, stdout, stderr, err,
257					map[string]any{"accepted": false, "error": err.Error()})
258			}
259			return failIO(stderr, err)
260		}
261		human := fmt.Sprintf("已登记器具 %s（%s），允许绝对误差 %g，状态：%s\n",
262			inst.ID, inst.Name, inst.AllowedError, inst.Status)
263		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "instrument": inst})
264	}
265	
266	func cmdStatus(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
267		fs := newFlagSet("status", &opts)
268		id := fs.String("id", "", "器具编号")
269		status := fs.String("status", "", "在用|停用|待校准")
270		if err := fs.Parse(args); err != nil {
271			fmt.Fprintln(stderr, "status 参数错误：", err)
272			return 2
273		}
274		if *id == "" || *status == "" {
275			fmt.Fprintln(stderr, "status 必须提供 --id、--status")
276			return 2
277		}
278		st, err := calibrate.ParseStatus(*status)
279		if err != nil {
280			fmt.Fprintln(stderr, err)
281			return 2
282		}
283		if err := l.SetStatus(*id, st); err != nil {
284			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
285				return failBusiness(opts, stdout, stderr, err,
286					map[string]any{"accepted": false, "error": err.Error()})
287			}
288			return failIO(stderr, err)
289		}
290		human := fmt.Sprintf("器具 %s 已切换为%s\n", *id, st)
291		return emit(opts, stdout, stderr, human,
292			map[string]any{"accepted": true, "id": *id, "status": st})
293	}
294	
295	func cmdCert(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
296		fs := newFlagSet("cert", &opts)
297		instrument := fs.String("instrument", "", "器具编号")
298		number := fs.String("number", "", "证书编号（全台账唯一）")
299		calDate := fs.String("cal-date", "", "校准日期 YYYY-MM-DD")
300		expiry := fs.String("expiry", "", "有效期截止日 YYYY-MM-DD")
301		method := fs.String("method", "", "校准方法")
302		measured := fs.String("error", "", "测得误差（有限数）")
303		summary := fs.String("summary", "", "证书摘要")
304		if err := fs.Parse(args); err != nil {
305			fmt.Fprintln(stderr, "cert 参数错误：", err)
306			return 2
307		}
308		missing := []string{}
309		for k, v := range map[string]string{
310			"--instrument": *instrument, "--number": *number, "--cal-date": *calDate,
311			"--expiry": *expiry, "--method": *method, "--error": *measured, "--summary": *summary,
312		} {
313			if strings.TrimSpace(v) == "" {
314				missing = append(missing, k)
315			}
316		}
317		if len(missing) > 0 {
318			fmt.Fprintln(stderr, "cert 缺少必填参数：", strings.Join(missing, "、"))
319			return 2
320		}
321		measuredErr, ok := parseFloat(stderr, *measured, "测得误差")
322		if !ok {
323			return 2
324		}
325		cert, duplicate, err := l.AddCertificate(calibrate.CertificateInput{
326			InstrumentID: *instrument,
327			Number:       *number,
328			CalDate:      *calDate,
329			Expiry:       *expiry,
330			Method:       *method,
331			Error:        measuredErr,
332			Summary:      *summary,
333		})
334		if err != nil {
335			if calibrate.IsValidation(err) || calibrate.IsConflict(err) || errors.Is(err, calibrate.ErrNotFound) {
336				return failBusiness(opts, stdout, stderr, err,
337					map[string]any{"accepted": false, "conflict": calibrate.IsConflict(err), "error": err.Error()})
338			}
339			return failIO(stderr, err)
340		}
341		note := "已录入新证书"
342		if duplicate {
343			note = "同号证书且内容一致，返回原证书，未增加历史记录"
344		}
345		// 证书结论只依赖本次证书自身的测得误差与所属器具登记的允许误差，
346		// 与录入反馈、最近证书、历史证书共用同一条规则（Certificate.Pass）；
347		// 不组装包含历史证书、使用拒绝记录与校准计划的完整核对结果。
348		inst, err := l.Instrument(cert.InstrumentID)
349		if err != nil {
350			return failIO(stderr, err)
351		}
352		verdict := "合格"
353		if !cert.Pass(inst.AllowedError) {
354			verdict = "超差"
355		}
356		human := fmt.Sprintf("%s：%s（器具 %s，校准日期 %s，截止日 %s，测得误差 %g，判定：%s）\n",
357			note, cert.Number, cert.InstrumentID, cert.CalDate, cert.Expiry, cert.Error, verdict)
358		return emit(opts, stdout, stderr, human,
359			map[string]any{"accepted": true, "duplicate": duplicate, "verdict": verdict, "certificate": cert})
360	}
361	
362	func cmdUse(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
363		fs := newFlagSet("use", &opts)
364		id := fs.String("id", "", "器具编号")
365		if err := fs.Parse(args); err != nil {
366			fmt.Fprintln(stderr, "use 参数错误：", err)
367			return 2
368		}
369		if strings.TrimSpace(*id) == "" {
370			fmt.Fprintln(stderr, "use 必须提供 --id")
371			return 2
372		}
373		d, err := l.RequestUse(*id)
374		if err != nil {
375			if errors.Is(err, calibrate.ErrNotFound) || calibrate.IsValidation(err) {
376				return failBusiness(opts, stdout, stderr, err,
377					map[string]any{"accepted": false, "recorded": false, "error": err.Error()})
378			}
379			return failIO(stderr, err)
380		}
381		if !d.Allowed {
382			var sb strings.Builder
383			sb.WriteString(fmt.Sprintf("拒绝使用器具 %s，已记录本次拒绝及原因：\n", *id))
384			for _, r := range d.Reasons {
385				sb.WriteString("  - " + r + "\n")
386			}
387			if opts.asJSON {
388				raw, _ := json.MarshalIndent(map[string]any{
389					"allowed": false, "recorded": true, "decision": d,
390				}, "", "  ")
391				fmt.Fprintln(stdout, string(raw))
392			}
393			fmt.Fprint(stderr, sb.String())
394			return 1
395		}
396		human := fmt.Sprintf("允许使用器具 %s，已记录本次申请。\n", *id)
397		return emit(opts, stdout, stderr, human,
398			map[string]any{"allowed": true, "recorded": true, "decision": d})
399	}
400	
401	func cmdReview(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
402		fs := newFlagSet("review", &opts)
403		id := fs.String("id", "", "器具编号")
404		if err := fs.Parse(args); err != nil {
405			fmt.Fprintln(stderr, "review 参数错误：", err)
406			return 2
407		}
408		if strings.TrimSpace(*id) == "" {
409			fmt.Fprintln(stderr, "review 必须提供 --id")
410			return 2
411		}
412		r, err := l.Review(*id)
413		if err != nil {
414			if errors.Is(err, calibrate.ErrNotFound) {
415				return failBusiness(opts, stdout, stderr, err,
416					map[string]any{"found": false, "error": err.Error()})
417			}
418			return failIO(stderr, err)
419		}
420		var sb strings.Builder
421		fmt.Fprintf(&sb, "器具 %s（%s）\n", r.Instrument.ID, r.Instrument.Name)
422		fmt.Fprintf(&sb, "  允许绝对误差：%g；当前状态：%s\n", r.Instrument.AllowedError, r.Instrument.Status)
423		if r.CanUse {
424			sb.WriteString("  当前能否使用：可以\n")
425		} else {
426			sb.WriteString("  当前能否使用：不可以，原因：\n")
427			for _, reason := range r.Reasons {
428				sb.WriteString("    - " + reason + "\n")
429			}
430		}
431		if r.Latest == nil {
432			sb.WriteString("  最近证书：无\n")
433		} else {
434			fmt.Fprintf(&sb, "  最近证书：%s（校准日期 %s，截止日 %s，判定：%s，%s）\n",
435				r.Latest.Number, r.Latest.CalDate, r.Latest.Expiry,
436				verdictText(r.Latest.Pass), expiryText(r.Latest.Expired))
437		}
438		if len(r.History) == 0 {
439			sb.WriteString("  历史证书：无\n")
440		} else {
441			sb.WriteString("  历史证书（按校准日期由近到远）：\n")
442			for _, c := range r.History {
443				fmt.Fprintf(&sb, "    - %s %s 截止 %s 误差 %g %s %s（%s）\n",
444					c.Number, c.CalDate, c.Expiry, c.Error,
445					verdictText(c.Pass), expiryText(c.Expired), c.Method)
446			}
447		}
448		if len(r.Rejections) == 0 {
449			sb.WriteString("  被拒绝的使用记录：无\n")
450		} else {
451			sb.WriteString("  被拒绝的使用记录（原因为申请当时冻结）：\n")
452			for _, u := range r.Rejections {
453				sb.WriteString("    - " + u.RequestedAt + "\n")
454				for _, reason := range u.Reasons {
455					sb.WriteString("        - " + reason + "\n")
456				}
457			}
458		}
459		if len(r.Plans) == 0 {
460			sb.WriteString("  校准计划：无\n")
461		} else {
462			sb.WriteString("  校准计划（含当前及已结束计划、改期记录与关联证书）：\n")
463			for _, p := range r.Plans {
464				head := fmt.Sprintf("    - %s %s 状态：%s", p.Number, p.PlannedDate, p.Status)
465				if p.Open() {
466					head += "（" + p.Marker + "）"
467				}
468				if p.OriginalDate != p.PlannedDate {
469					head += fmt.Sprintf("，最初计划日期 %s", p.OriginalDate)
470				}
471				head += "，说明：" + p.Note + "\n"
472				sb.WriteString(head)
473				for _, ch := range p.Changes {
474					fmt.Fprintf(&sb, "        改期 %s → %s（%s），原因：%s\n",
475						ch.From, ch.To, ch.ChangedAt, ch.Reason)
476				}
477				if p.Status == calibrate.PlanStatusCanceled {
478					fmt.Fprintf(&sb, "        取消于 %s，原因：%s\n", p.CanceledAt, p.CancelReason)
479				}
480				if p.Status == calibrate.PlanStatusDone {
481					fmt.Fprintf(&sb, "        完成于 %s，证书 %s\n", p.CompletedAt, p.CertificateNumber)
482				}
483			}
484		}
485		return emit(opts, stdout, stderr, sb.String(), r)
486	}
487	
488	func verdictText(pass bool) string {
489		if pass {
490			return "合格"
491		}
492		return "超差"
493	}
494	
495	func expiryText(expired bool) string {
496		if expired {
497			return "已到期"
498		}
499		return "未到期"
500	}
501	
502	func cmdList(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
503		fs := newFlagSet("list", &opts)
504		if err := fs.Parse(args); err != nil {
505			fmt.Fprintln(stderr, "list 参数错误：", err)
506			return 2
507		}
508		instruments := l.Instruments()
509		var sb strings.Builder
510		if len(instruments) == 0 {
511			sb.WriteString("台账中还没有器具。\n")
512		}
513		for _, in := range instruments {
514			fmt.Fprintf(&sb, "%s\t%s\t允许误差 %g\t%s\n", in.ID, in.Name, in.AllowedError, in.Status)
515		}
516		return emit(opts, stdout, stderr, sb.String(),
517			map[string]any{"instruments": instruments, "count": len(instruments)})
518	}
519	
520	// failPlanBusiness 是计划类命令共用的业务拒绝输出（退出码 1）。
521	func failPlanBusiness(opts options, stdout, stderr io.Writer, err error, extra map[string]any) int {
522		resp := map[string]any{"accepted": false, "error": err.Error()}
523		for k, v := range extra {
524			resp[k] = v
525		}
526		return failBusiness(opts, stdout, stderr, err, resp)
527	}
528	
529	func cmdPlan(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
530		fs := newFlagSet("plan", &opts)
531		instrument := fs.String("instrument", "", "器具编号")
532		number := fs.String("number", "", "计划编号（全台账唯一，不可复用）")
533		date := fs.String("date", "", "计划日期 YYYY-MM-DD（不早于今天）")
534		note := fs.String("note", "", "非空计划说明")
535		if err := fs.Parse(args); err != nil {
536			fmt.Fprintln(stderr, "plan 参数错误：", err)
537			return 2
538		}
539		missing := []string{}
540		for k, v := range map[string]string{
541			"--instrument": *instrument, "--number": *number, "--date": *date, "--note": *note,
542		} {
543			if strings.TrimSpace(v) == "" {
544				missing = append(missing, k)
545			}
546		}
547		if len(missing) > 0 {
548			fmt.Fprintln(stderr, "plan 缺少必填参数：", strings.Join(missing, "、"))
549			return 2
550		}
551		p, err := l.CreatePlan(calibrate.PlanInput{
552			Number: *number, InstrumentID: *instrument, Date: *date, Note: *note,
553		})
554		if err != nil {
555			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
556				return failPlanBusiness(opts, stdout, stderr, err, nil)
557			}
558			return failIO(stderr, err)
559		}
560		human := fmt.Sprintf("已为器具 %s 建立校准计划 %s，计划日期 %s，说明：%s\n",
561			p.InstrumentID, p.Number, p.PlannedDate, p.Note)
562		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "plan": p})
563	}
564	
565	func cmdReschedule(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
566		fs := newFlagSet("reschedule", &opts)
567		number := fs.String("number", "", "计划编号")
568		date := fs.String("date", "", "新计划日期 YYYY-MM-DD（不早于今天）")
569		reason := fs.String("reason", "", "非空改期原因")
570		if err := fs.Parse(args); err != nil {
571			fmt.Fprintln(stderr, "reschedule 参数错误：", err)
572			return 2
573		}
574		missing := []string{}
575		for k, v := range map[string]string{
576			"--number": *number, "--date": *date, "--reason": *reason,
577		} {
578			if strings.TrimSpace(v) == "" {
579				missing = append(missing, k)
580			}
581		}
582		if len(missing) > 0 {
583			fmt.Fprintln(stderr, "reschedule 缺少必填参数：", strings.Join(missing, "、"))
584			return 2
585		}
586		p, err := l.ReschedulePlan(*number, *date, *reason)
587		if err != nil {
588			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
589				return failPlanBusiness(opts, stdout, stderr, err, nil)
590			}
591			return failIO(stderr, err)
592		}
593		human := fmt.Sprintf("计划 %s 已改期为 %s（第 %d 次改期）。\n",
594			p.Number, p.PlannedDate, len(p.Changes))
595		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "plan": p})
596	}
597	
598	func cmdCancel(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
599		fs := newFlagSet("cancel", &opts)
600		number := fs.String("number", "", "计划编号")
601		reason := fs.String("reason", "", "非空取消原因")
602		if err := fs.Parse(args); err != nil {
603			fmt.Fprintln(stderr, "cancel 参数错误：", err)
604			return 2
605		}
606		if strings.TrimSpace(*number) == "" || strings.TrimSpace(*reason) == "" {
607			fmt.Fprintln(stderr, "cancel 必须提供 --number、--reason")
608			return 2
609		}
610		p, err := l.CancelPlan(*number, *reason)
611		if err != nil {
612			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
613				return failPlanBusiness(opts, stdout, stderr, err, nil)
614			}
615			return failIO(stderr, err)
616		}
617		human := fmt.Sprintf("计划 %s 已于 %s 取消，原因：%s；不再列入待办。\n",
618			p.Number, p.CanceledAt, p.CancelReason)
619		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "plan": p})
620	}
621	
622	func cmdComplete(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
623		fs := newFlagSet("complete", &opts)
624		number := fs.String("number", "", "计划编号")
625		certificate := fs.String("certificate", "", "证书编号")
626		if err := fs.Parse(args); err != nil {
627			fmt.Fprintln(stderr, "complete 参数错误：", err)
628			return 2
629		}
630		if strings.TrimSpace(*number) == "" || strings.TrimSpace(*certificate) == "" {
631			fmt.Fprintln(stderr, "complete 必须提供 --number、--certificate")
632			return 2
633		}
634		p, idempotent, err := l.CompletePlan(*number, *certificate)
635		if err != nil {
636			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
637				return failPlanBusiness(opts, stdout, stderr, err, nil)
638			}
639			return failIO(stderr, err)
640		}
641		note := "已完成"
642		if idempotent {
643			note = "该计划已由此证书完成，返回原结果，未刷新完成时间"
644		}
645		human := fmt.Sprintf("%s：计划 %s，证书 %s，完成时间 %s。\n",
646			note, p.Number, p.CertificateNumber, p.CompletedAt)
647		return emit(opts, stdout, stderr, human,
648			map[string]any{"accepted": true, "idempotent": idempotent, "plan": p})
649	}
650	
651	func cmdTodos(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
652		fs := newFlagSet("todos", &opts)
653		instrument := fs.String("instrument", "", "只看该器具编号的待办")
654		if err := fs.Parse(args); err != nil {
655			fmt.Fprintln(stderr, "todos 参数错误：", err)
656			return 2
657		}
658		items, err := l.Todos(*instrument)
659		if err != nil {
660			if errors.Is(err, calibrate.ErrNotFound) {
661				return failBusiness(opts, stdout, stderr, err,
662					map[string]any{"found": false, "error": err.Error()})
663			}
664			return failIO(stderr, err)
665		}
666		var sb strings.Builder
667		if len(items) == 0 {
668			sb.WriteString("无待办。\n")
669		}
670		for _, it := range items {
671			fmt.Fprintf(&sb, "%s\t%s（%s，%s）\t%s\t%s\t%s\n",
672				it.PlanNumber, it.InstrumentID, it.InstrumentName, it.Status,
673				it.PlannedDate, it.Marker, it.Note)
674		}
675		return emit(opts, stdout, stderr, sb.String(),
676			map[string]any{"todos": items, "count": len(items)})
677	}
