323		plan := func(path string) result {
324			return runArgs(t, "plan", "-f", path,
325				"--instrument", "DUP", "--number", "PL-1",
326				"--date", "2030-10-20", "--note", "计划")
327		}
328		if r := plan(a); r.code != 0 {
