330		}
331		if r := plan(b); r.code != 0 {
332			t.Fatalf("b 使用同号计划应独立通过: %s", r.stderr)
333		}
334		if r := plan(a); r.code != 1 {
335			t.Fatalf("a 中重复计划号应被拒，得到 %d", r.code)
336		}
337	
338		// 查询“最近证书”只看目标文件：a、b 的 C-1 校准日期不同。
