// 多个文件参数交错出现时，按命令行顺序以最后一次为准。
func TestMultipleFileFlagsLastWins(t *testing.T) {
	dir := chdirTemp(t)
	a := filepath.Join(dir, "a.json")
	b := filepath.Join(dir, "b.json")
