	if r3.code != 0 || strings.Contains(r3.stdout, "M-1") {
		t.Fatalf("最后一次为空路径时不应再使用前面的 c，stdout=%q", r3.stdout)
	}
	if fileExists(t, none) {
		t.Fatal("查询不应创建仅作为中间值出现过的文件")
	}
}

