22	// certFullArgs 构造一条录入证书的完整参数，允许显式指定每个字段。
23	func certFullArgs(path, instrument, number, calDate, expiry, errVal string) []string {
24		return []string{"cert", "-f", path,
25			"--instrument", instrument, "--number", number,
26			"--cal-date", calDate, "--expiry", expiry,
27			"--method", "回归方法", "--error", errVal, "--summary", "回归摘要"}
28	}
