30	func registerAllowed(t *testing.T, path, id, allowed string) {
31		t.Helper()
32		if r := runArgs(t, "register", "-f", path,
33			"--id", id, "--name", "器具-"+id, "--allowed", allowed); r.code != 0 {
34			t.Fatalf("登记器具 %s（允许误差 %s）失败 code=%d stderr=%s", id, allowed, r.code, r.stderr)
35		}
36	}
