38	func mustParseFloat(t *testing.T, raw string) float64 {
39		t.Helper()
40		v, err := strconv.ParseFloat(raw, 64)
41		if err != nil {
42			t.Fatalf("测试用例的误差 %q 不是数字：%v", raw, err)
43		}
44		return v
45	}
