47	// certCLIResult 是 cert 命令 --json 成功输出的最小解析结构。
48	type certCLIResult struct {
49		Accepted    bool `json:"accepted"`
50		Duplicate   bool `json:"duplicate"`
51		Verdict     string
52		Certificate struct {
53			Number       string  `json:"number"`
54			InstrumentID string  `json:"instrument_id"`
55			CalDate      string  `json:"cal_date"`
56			Expiry       string  `json:"expiry"`
57			Error        float64 `json:"error"`
58		} `json:"certificate"`
59	}
60	
61	// runCertJSON 以 --json 方式录入（或幂等重提）证书并解析结论。
62	func runCertJSON(t *testing.T, args []string) (result, certCLIResult) {
63		t.Helper()
64		r := runArgs(t, append(append([]string{}, args...), "--json")...)
65		var got certCLIResult
66		if r.code == 0 {
67			if err := json.Unmarshal([]byte(r.stdout), &got); err != nil {
68				t.Fatalf("cert JSON 解析失败: %v\n%s", err, r.stdout)
69			}
70		}
71		return r, got
72	}
