74	// assertCertVerdict 核对同一条证书内容在普通文字与 --json 下结论一致：
75	// 首次以普通文字录入（应明确“已录入新证书”），再以 --json 幂等重提，
76	// 两种表达的结论必须相同，JSON 中的编号、所属器具、带符号误差都对应该内容。
77	func assertCertVerdict(t *testing.T, args []string, instrument, wantVerdict, wantErrRaw string) certCLIResult {
78		t.Helper()
79		wantErr := mustParseFloat(t, wantErrRaw)
80		number := args[flagValueIndex(t, args, "--number")+1]
81	
82		human := runArgs(t, args...)
83		if human.code != 0 {
84			t.Fatalf("证书 %s 录入失败 code=%d stderr=%s", number, human.code, human.stderr)
85		}
86		if !strings.Contains(human.stdout, "已录入新证书") {
87			t.Fatalf("证书 %s 应作为新证书录入成功：%q", number, human.stdout)
88		}
89		if !strings.Contains(human.stdout, "判定："+wantVerdict) {
90			t.Fatalf("证书 %s 普通文字应显示判定：%s，实际 %q", number, wantVerdict, human.stdout)
91		}
92		// 超差只是证书结论，不是录入被拒：不能写成“已拒绝”，也不能走退出码 1/2。
93		if strings.Contains(human.stderr, "已拒绝") {
94			t.Fatalf("证书 %s 的超差结论不应被当成业务拒绝：%q", number, human.stderr)
95		}
96		// 普通文字也必须保留原始带符号误差（%g 对 -0.5 这类值保留符号）。
97		if !strings.Contains(human.stdout, "测得误差 "+wantErrRaw) {
98			t.Fatalf("证书 %s 普通文字应保留带符号误差 %s，实际 %q", number, wantErrRaw, human.stdout)
99		}
100	
101		dup, js := runCertJSON(t, args)
102		if dup.code != 0 {
103			t.Fatalf("证书 %s 幂等重提失败 code=%d stderr=%s", number, dup.code, dup.stderr)
104		}
105		if !js.Accepted || !js.Duplicate {
106			t.Fatalf("证书 %s 第二次提交应 accepted=true 且 duplicate=true，得到 %+v", number, js)
107		}
108		if js.Verdict != wantVerdict {
109			t.Fatalf("证书 %s 的 JSON 结论应为 %s，得到 %q", number, wantVerdict, js.Verdict)
110		}
111		if js.Certificate.Number != number {
112			t.Fatalf("JSON 证书编号应对应本次提交 %s，得到 %s", number, js.Certificate.Number)
113		}
114		if js.Certificate.InstrumentID != instrument {
115			t.Fatalf("证书 %s 的 JSON 所属器具应为 %s，得到 %s",
116				number, instrument, js.Certificate.InstrumentID)
117		}
118		if js.Certificate.Error != wantErr {
119			t.Fatalf("证书 %s 的 JSON 测得误差应为带符号的 %g，得到 %g",
120				number, wantErr, js.Certificate.Error)
121		}
122		return js
123	}
