232	// TestCertVerdictZeroAllowedError 覆盖允许误差为零的器具：零误差仍合格，
233	// 任意非零误差（无论正负）都超差，且超差证书仍录入成功。
234	func TestCertVerdictZeroAllowedError(t *testing.T) {
235		dir := chdirTemp(t)
236		path := filepath.Join(dir, "台账.json")
237		registerAllowed(t, path, "M-0", "0")
238	
239		now := time.Now()
240		past := func(days int) string { return now.AddDate(0, 0, -days).Format(calibrate.DateLayout) }
241		future := now.AddDate(10, 0, 0).Format(calibrate.DateLayout)
242	
243		cases := []struct {
244			number string
245			err    string
246			want   string
247		}{
248			{"C-ZERO", "0", "合格"},
249			{"C-POS", "0.0001", "超差"},
250			{"C-NEG", "-0.0001", "超差"},
251		}
252		for i, tc := range cases {
253			assertCertVerdict(t,
254				certFullArgs(path, "M-0", tc.number, past(20+i), future, tc.err),
255				"M-0", tc.want, tc.err)
256		}
257		rv := mustReviewJSON(t, path, "M-0")
258		got := map[string]bool{}
259		for _, h := range rv.History {
260			got[h.Number] = h.Pass
261		}
262		if !got["C-ZERO"] || got["C-POS"] || got["C-NEG"] {
263			t.Fatalf("零允许误差下结论错误：%v", got)
264		}
265	}
266	
267	// TestCertVerdictFollowsEachInstrumentLimit 同一测得误差放在允许误差不同的
268	// 器具上，结论分别遵从各自限值，不能混用另一件器具的数据。
269	func TestCertVerdictFollowsEachInstrumentLimit(t *testing.T) {
270		dir := chdirTemp(t)
271		path := filepath.Join(dir, "台账.json")
272		registerAllowed(t, path, "M-LOOSE", "1")
273		registerAllowed(t, path, "M-TIGHT", "0.1")
274	
275		now := time.Now()
276		cal := now.AddDate(0, 0, -5).Format(calibrate.DateLayout)
277		expiry := now.AddDate(10, 0, 0).Format(calibrate.DateLayout)
278	
279		// 同一次校准日、同一个 -0.5 误差：宽松器具合格，严格器具超差。
280		looseArgs := certFullArgs(path, "M-LOOSE", "C-LOOSE", cal, expiry, "-0.5")
281		tightArgs := certFullArgs(path, "M-TIGHT", "C-TIGHT", cal, expiry, "-0.5")
282	
283		looseHuman := runArgs(t, looseArgs...)
284		if looseHuman.code != 0 || !strings.Contains(looseHuman.stdout, "判定：合格") {
285			t.Fatalf("允许误差 1 的器具录入 -0.5 应合格：code=%d %q %s",
286				looseHuman.code, looseHuman.stdout, looseHuman.stderr)
287		}
288		tightHuman := runArgs(t, tightArgs...)
289		if tightHuman.code != 0 || !strings.Contains(tightHuman.stdout, "判定：超差") {
290			t.Fatalf("允许误差 0.1 的器具录入 -0.5 应超差但录入成功：code=%d %q %s",
291				tightHuman.code, tightHuman.stdout, tightHuman.stderr)
292		}
293	
294		// JSON 中证书编号、所属器具、误差都对应本次提交，结论与文字一致。
295		_, looseJSON := runCertJSON(t, looseArgs)
296		_, tightJSON := runCertJSON(t, tightArgs)
297		if looseJSON.Verdict != "合格" || tightJSON.Verdict != "超差" {
298			t.Fatalf("JSON 结论串台：loose=%q tight=%q", looseJSON.Verdict, tightJSON.Verdict)
299		}
300		if looseJSON.Certificate.Number != "C-LOOSE" || looseJSON.Certificate.InstrumentID != "M-LOOSE" ||
301			looseJSON.Certificate.Error != -0.5 {
302			t.Fatalf("宽松器具的 JSON 证书字段不对应本次提交：%+v", looseJSON.Certificate)
303		}
304		if tightJSON.Certificate.Number != "C-TIGHT" || tightJSON.Certificate.InstrumentID != "M-TIGHT" ||
305			tightJSON.Certificate.Error != -0.5 {
306			t.Fatalf("严格器具的 JSON 证书字段不对应本次提交：%+v", tightJSON.Certificate)
307		}
308	
309		// 各器具的最近证书与结论互不混入。
310		looseReview := mustReviewJSON(t, path, "M-LOOSE")
311		tightReview := mustReviewJSON(t, path, "M-TIGHT")
312		if looseReview.Latest == nil || looseReview.Latest.Number != "C-LOOSE" || !looseReview.Latest.Pass {
313			t.Fatalf("宽松器具最近证书应是自身的合格证书：%+v", looseReview.Latest)
314		}
315		if tightReview.Latest == nil || tightReview.Latest.Number != "C-TIGHT" || tightReview.Latest.Pass {
316			t.Fatalf("严格器具最近证书应是自身的超差证书：%+v", tightReview.Latest)
317		}
318	}
319	
320	// TestCertVerdictIndependentOfInstrumentStatus 证书结论只属于证书本身：
321	// 待校准或停用器具录入合格证书，录入结果仍显示合格；“当前能否使用”另由
322	// 核对按状态判断，不能拿器具的使用判断替换证书结论。
323	func TestCertVerdictIndependentOfInstrumentStatus(t *testing.T) {
324		dir := chdirTemp(t)
325		path := filepath.Join(dir, "台账.json")
326		registerAllowed(t, path, "M-PENDING", "0.5") // 新登记即为待校准
327		registerAllowed(t, path, "M-RETIRED", "0.5")
328		if r := runArgs(t, "status", "-f", path, "--id", "M-RETIRED", "--status", "停用"); r.code != 0 {
329			t.Fatalf("切换停用失败 code=%d stderr=%s", r.code, r.stderr)
330		}
331	
332		now := time.Now()
333		cal := now.AddDate(0, 0, -7).Format(calibrate.DateLayout)
334		expiry := now.AddDate(10, 0, 0).Format(calibrate.DateLayout)
335	
336		for _, tc := range []struct {
337			id, number, reason string
338		}{
339			{"M-PENDING", "C-PENDING", "待校准"},
340			{"M-RETIRED", "C-RETIRED", "停用"},
341		} {
342			args := certFullArgs(path, tc.id, tc.number, cal, expiry, "-0.2")
343			human := runArgs(t, args...)
344			if human.code != 0 || !strings.Contains(human.stdout, "判定：合格") {
345				t.Fatalf("%s 器具录入合格证书应显示合格：code=%d %q %s",
346					tc.reason, human.code, human.stdout, human.stderr)
347			}
348			_, js := runCertJSON(t, args)
349			if js.Verdict != "合格" || js.Certificate.Number != tc.number ||
350				js.Certificate.InstrumentID != tc.id || js.Certificate.Error != -0.2 {
351				t.Fatalf("%s 器具的证书 JSON 字段不应被使用判断替换：%+v", tc.reason, js)
352			}
353	
354			// 证书本身合格，但器具当前仍不可使用，原因来自状态而非证书超差。
355			rv := mustReviewJSON(t, path, tc.id)
356			if rv.CanUse {
357				t.Fatalf("%s 器具不应因证书合格就能使用", tc.reason)
358			}
359			if !containsStd(rv.Reasons, tc.reason) {
360				t.Fatalf("不可使用的原因应包含%s，得到 %v", tc.reason, rv.Reasons)
361			}
362			if rv.Latest == nil || !rv.Latest.Pass {
363				t.Fatalf("%s 器具的最近证书自身结论仍应是合格：%+v", tc.reason, rv.Latest)
364			}
365		}
366	}
367	
368	// TestBackfillOlderPassingCertKeepsNewerFailingLatest 守住补录主场景：
369	// 器具在用、已有一张校准日期较新的超差证书，再补录一张校准日期较早、合格且
370	// 未到期的证书——补录结果必须显示旧证书合格并进入历史，但最近证书仍是较新
371	// 的超差证书，申请使用仍因最近证书超差被拒绝。先后依据校准日期，而不是证书
372	// 编号或录入顺序（这里较新证书编号 C-1 更小、录入更早）。
373	func TestBackfillOlderPassingCertKeepsNewerFailingLatest(t *testing.T) {
374		dir := chdirTemp(t)
375		path := filepath.Join(dir, "台账.json")
376		registerAllowed(t, path, "M-1", "0.5")
377		if r := runArgs(t, "status", "-f", path, "--id", "M-1", "--status", "在用"); r.code != 0 {
378			t.Fatalf("切换在用失败 code=%d stderr=%s", r.code, r.stderr)
379		}
380	
381		now := time.Now()
382		newerCal := now.AddDate(0, 0, -30).Format(calibrate.DateLayout)
383		olderCal := now.AddDate(0, 0, -200).Format(calibrate.DateLayout)
384		expiry := now.AddDate(10, 0, 0).Format(calibrate.DateLayout)
385	
386		// 先录入校准日期较新的超差证书（编号 C-1，按编号反而更小）。
387		newer := certFullArgs(path, "M-1", "C-1", newerCal, expiry, "0.8")
388		r := runArgs(t, newer...)
389		if r.code != 0 || !strings.Contains(r.stdout, "已录入新证书") ||
390			!strings.Contains(r.stdout, "判定：超差") {
391			t.Fatalf("较新超差证书应录入成功并显示超差：code=%d %q %s", r.code, r.stdout, r.stderr)
392		}
393	
394		// 补录前：历史 1 张、最近证书超差、使用被拒绝并留痕。
395		before := mustReviewJSON(t, path, "M-1")
396		if len(before.History) != 1 || before.Latest == nil || before.Latest.Number != "C-1" || before.Latest.Pass {
397			t.Fatalf("补录前最近证书应是超差的 C-1：%+v", before)
398		}
399		use1 := runArgs(t, "use", "--id", "M-1", "-f", path)
400		if use1.code != 1 || !strings.Contains(use1.stderr, "超差") {
401			t.Fatalf("最近证书超差应拒绝使用，code=%d stderr=%q", use1.code, use1.stderr)
402		}
403	
404		// 补录校准日期较早、合格、未到期的旧证书（编号 C-9 更大、录入更晚）。
405		older := certFullArgs(path, "M-1", "C-9", olderCal, expiry, "-0.1")
406		jr, js := runCertJSON(t, older)
407		if jr.code != 0 || !js.Accepted || js.Duplicate {
408			t.Fatalf("旧合格证书应作为新证书录入成功：code=%d stdout=%q stderr=%s",
409				jr.code, jr.stdout, jr.stderr)
410		}
411		if js.Verdict != "合格" {
412			t.Fatalf("补录结果必须显示旧证书自身合格，不能被最近证书的超差覆盖，得到 %q", js.Verdict)
413		}
414		if js.Certificate.Number != "C-9" || js.Certificate.InstrumentID != "M-1" ||
415			js.Certificate.Error != -0.1 || js.Certificate.CalDate != olderCal {
416			t.Fatalf("JSON 证书字段应对应本次补录：%+v", js.Certificate)
417		}
418		// 同内容普通文字重提：结论仍为合格，并标明返回原证书。
419		human2 := runArgs(t, older...)
420		if human2.code != 0 || !strings.Contains(human2.stdout, "判定：合格") ||
421			!strings.Contains(human2.stdout, "未增加历史") {
422			t.Fatalf("普通文字下补录证书也应显示合格：code=%d %q", human2.code, human2.stdout)
423		}
424	
425		// 补录后：历史增加这张证书；最近证书仍是校准日期较新的超差 C-1，
426		// 不能因为补录证书合格就解除使用限制；器具状态保持在用。
427		after := mustReviewJSON(t, path, "M-1")
428		if len(after.History) != len(before.History)+1 {
429			t.Fatalf("补录应只增加一张历史证书：%d -> %d",
430				len(before.History), len(after.History))
431		}
432		if after.Instrument.Status != "在用" {
433			t.Fatalf("补录证书不应改写器具状态，得到 %s", after.Instrument.Status)
434		}
435		if after.Latest == nil || after.Latest.Number != "C-1" ||
436			after.Latest.CalDate != newerCal || after.Latest.Error != 0.8 || after.Latest.Pass {
437			t.Fatalf("最近证书必须仍是较新的超差 C-1（按校准日期而非编号/录入顺序）：%+v", after.Latest)
438		}
439		found := false
440		for i := range after.History {
441			h := after.History[i]
442			if h.Number == "C-9" {
443				found = true
444				if !h.Pass {
445					t.Fatal("历史中的旧证书应显示合格")
446				}
447				if h.Expired {
448					t.Fatal("补录的旧证书应未到期")
449				}
450				if h.Error != -0.1 {
451					t.Fatalf("旧证书应保留原始带符号误差 -0.1，得到 %g", h.Error)
452				}
453			}
454			if h.Number == "C-1" && !h.Pass {
455				// 较新证书结论同样保持超差。
456			}
457		}
458		if !found {
459			t.Fatalf("历史中应增加补录的 C-9：%+v", after.History)
460		}
461		if after.CanUse || !containsStd(after.Reasons, "超差") {
462			t.Fatalf("补录合格旧证书不应解除使用限制：canUse=%v reasons=%v",
463				after.CanUse, after.Reasons)
464		}
465	
466		// 再次申请使用：仍因最近证书 C-1 超差被拒绝，并新增一条拒绝留痕。
467		use2 := runArgs(t, "use", "--id", "M-1", "-f", path, "--json")
468		if use2.code != 1 || !strings.Contains(use2.stdout, `"allowed": false`) ||
469			!strings.Contains(use2.stdout, "超差") {
470			t.Fatalf("补录后申请使用仍应因最近证书超差被拒绝：code=%d stdout=%q",
471				use2.code, use2.stdout)
472		}
473		final := mustReviewJSON(t, path, "M-1")
474		if len(final.Rejections) != 2 {
475			t.Fatalf("两次拒绝都应留痕且补录不改写历史，得到 %d 条", len(final.Rejections))
476		}
477		for i, rej := range final.Rejections {
478			if rej.Allowed || !containsStd(rej.Reasons, "超差") {
479				t.Fatalf("第 %d 条拒绝记录应保留申请当时的超差原因：%+v", i+1, rej)
480			}
481		}
482	}
483	
484	// TestBackfillOlderFailingCertKeepsInstrumentUsable 反方向守住同一条边界：
485	// 器具在用、最近证书合格时补录一张更早的超差证书，补录结果必须如实显示超差，
486	// 但最近证书与当前能否使用都不被这张旧证书改变。
487	func TestBackfillOlderFailingCertKeepsInstrumentUsable(t *testing.T) {
488		dir := chdirTemp(t)
489		path := filepath.Join(dir, "台账.json")
490		registerAllowed(t, path, "M-2", "0.5")
491		if r := runArgs(t, "status", "-f", path, "--id", "M-2", "--status", "在用"); r.code != 0 {
492			t.Fatalf("切换在用失败 code=%d stderr=%s", r.code, r.stderr)
493		}
494	
495		now := time.Now()
496		newerCal := now.AddDate(0, 0, -30).Format(calibrate.DateLayout)
497		olderCal := now.AddDate(0, 0, -200).Format(calibrate.DateLayout)
498		expiry := now.AddDate(10, 0, 0).Format(calibrate.DateLayout)
499	
500		// 较新的合格证书：器具当前可使用。
501		newer := certFullArgs(path, "M-2", "C-2", newerCal, expiry, "0.1")
502		if r := runArgs(t, newer...); r.code != 0 ||
503			!strings.Contains(r.stdout, "判定：合格") {
504			t.Fatalf("较新合格证书录入异常：code=%d %q %s", r.code, r.stdout, r.stderr)
505		}
506		if u := runArgs(t, "use", "--id", "M-2", "-f", path); u.code != 0 {
507			t.Fatalf("最近证书合格未到期时应允许使用，code=%d stderr=%s", u.code, u.stderr)
508		}
509	
510		// 补录更早的超差证书：本次录入结果必须明确显示超差。
511		older := certFullArgs(path, "M-2", "C-1", olderCal, expiry, "-5")
512		jr, js := runCertJSON(t, older)
513		if jr.code != 0 || !js.Accepted || js.Duplicate {
514			t.Fatalf("旧超差证书也应作为新证书录入成功：code=%d stdout=%q stderr=%s",
515				jr.code, jr.stdout, jr.stderr)
516		}
517		if js.Verdict != "超差" || js.Certificate.Number != "C-1" ||
518			js.Certificate.InstrumentID != "M-2" || js.Certificate.Error != -5 {
519			t.Fatalf("补录结果应如实显示本次证书超差且字段对应提交：%+v", js)
520		}
521	
522		// 最近证书仍是较新的合格 C-2，器具当前可以使用，使用申请不因旧超差证书被拒。
523		rv := mustReviewJSON(t, path, "M-2")
524		if len(rv.History) != 2 {
525			t.Fatalf("补录应使历史变为 2 张，得到 %d", len(rv.History))
526		}
527		if rv.Latest == nil || rv.Latest.Number != "C-2" || !rv.Latest.Pass {
528			t.Fatalf("最近证书应仍是较新的合格 C-2：%+v", rv.Latest)
529		}
530		if !rv.CanUse || len(rv.Reasons) != 0 {
531			t.Fatalf("最近证书合格时旧超差证书不应限制使用：canUse=%v reasons=%v",
532				rv.CanUse, rv.Reasons)
533		}
534		for _, h := range rv.History {
535			switch h.Number {
536			case "C-1":
537				if h.Pass || h.Error != -5 {
538					t.Fatalf("旧超差证书应保留超差结论与带符号误差：%+v", h)
539				}
540			case "C-2":
541				if !h.Pass {
542					t.Fatalf("较新合格证书不应被旧证书改写结论：%+v", h)
543				}
544			}
545		}
546		if u := runArgs(t, "use", "--id", "M-2", "-f", path, "--json"); u.code != 0 ||
547			!strings.Contains(u.stdout, `"allowed": true`) {
548			t.Fatalf("补录旧超差证书后仍应允许使用：code=%d stdout=%q stderr=%s",
549				u.code, u.stdout, u.stderr)
550		}
551	}
552	
553	func containsStd(haystack []string, needle string) bool {
554		for _, s := range haystack {
555			if strings.Contains(s, needle) {
556				return true
557			}
558		}
559		return false
560	}
